from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
from medicaments import window
l=Lesson('Blépharospasme')
l.add('Le blépharospasme est une fermeture involontaire des paupières par contraction musculaire. Les {distinctions initiales} séparent la dystonie, la réponse à une irritation et les mouvements qui leur ressemblent. Une douleur oculaire ou une baisse visuelle impose un tri prioritaire.',paras('Au sens neurologique, le blépharospasme essentiel est une dystonie focale, habituellement bilatérale. Dans une consultation pour paupière qui se ferme ou tressaute, le terme employé par le patient peut aussi désigner une myokymie, un tic ou une difficulté de réouverture.', 'Le spasme réflexe provoqué par une cornée douloureuse ne se traite pas comme une dystonie. Un ptosis correspond à une paupière tombante, et non à la même contraction involontaire.')+table(['Observation','Question clinique'],[['Fermeture forcée bilatérale répétée.','Dystonie ou réponse à une irritation ?'],['Petit frémissement localisé.','Myokymie ou autre mouvement ?'],['Contractions d’une hémiface.','Spasme hémifacial ?'],['Difficulté à rouvrir ou paupière tombante.','Apraxie, ptosis ou faiblesse ?']]),(1,2,6,7,8,10))
l.add('La dystonie palpébrale est rare, tandis que les petits tressautements sont courants. Les {limites des données} empêchent de classer ces dix diagnostics par fréquence suisse mesurée. Le contexte clinique détermine leur priorité.',paras('Les revues décrivent surtout un début du blépharospasme essentiel à l’âge adulte, avec un retentissement parfois majeur. La fermeture peut gêner lecture, déplacements et conduite sans correspondre à une destruction de la fonction visuelle.', 'Les sources consultées ne fournissent pas de prévalences suisses comparables pour l’ensemble des causes retenues. La liste est organisée pour le raisonnement ; une urgence cornéenne ne devient pas moins importante parce qu’une myokymie est fréquente.'),(2,6,7,10,11))
anatomie=l.subwindow('anatomie','Fermeture, ouverture et réflexe cornéen',paras('L’orbiculaire ferme les paupières sous la commande du nerf facial, septième nerf crânien. Le releveur de la paupière supérieure participe à l’ouverture sous la commande du nerf oculomoteur, troisième nerf crânien.', 'Le réflexe cornéen comporte une afférence sensitive par le trijumeau et une réponse motrice par le facial vers l’orbiculaire. Une irritation de surface peut ainsi provoquer clignement, larmoiement et fermeture protectrice.', 'Une fermeture excessive, un défaut de commande de l’ouverture et une faiblesse du releveur sont des mécanismes différents. Leur distinction repose sur l’observation et l’examen, pas sur le seul mot de spasme.'),(3,4,6,7))
l.add('L’ouverture et la fermeture mobilisent des muscles et des circuits différents. Les {bases anatomiques et physiologiques} expliquent pourquoi une irritation et une dystonie peuvent produire une plainte proche. Elles peuvent également coexister.',paras(anatomie)+paras('La dystonie est liée à un fonctionnement anormal de réseaux moteurs et sensorimoteurs ; les revues impliquent plusieurs circuits, pas une lésion unique obligatoire des ganglions de la base. Les anomalies décrites en recherche ne constituent pas un examen diagnostique de routine.', 'Un geste antagoniste est une manœuvre sensorielle qui diminue temporairement le spasme, par exemple un contact léger du visage. Cet effet ne signifie pas que le trouble est volontaire ou imaginaire.', 'La toxine botulique réduit localement la transmission neuromusculaire et la contraction. Elle agit sur le symptôme moteur sans corriger nécessairement l’ensemble du mécanisme de la maladie.'),(3,4,5,6,7))
l.add('Les {urgences à exclure} concernent surtout la vision, l’intégrité de l’œil et les signes neurologiques associés. Un œil douloureux fermé ne doit pas être étiqueté dystonique sans examen. Les antécédents de lentilles ou de chirurgie augmentent la vigilance.',table(['Priorité','🚩 Constat','Conduite'],[['E1 — Atteinte cornéenne.','Douleur, photophobie, infiltrat ou baisse visuelle, surtout avec lentilles.','Avis ophtalmologique urgent.'],['E2 — Traumatisme.','Projection, corps étranger, produit chimique ou suspicion de plaie.','Prise en charge urgente adaptée, sans manipulation forcée d’une plaie suspecte.'],['E3 — Glaucome aigu ou inflammation profonde.','Œil très douloureux, halos, céphalée, nausées ou pupille anormale.','Évaluation ophtalmologique immédiate selon le tableau.'],['E4 — Atteinte neurologique.','Déficit nouveau, trouble oculomoteur, ptosis aigu ou autre anomalie focale.','Évaluation urgente de la cause, distincte d’une dystonie habituelle.'],['E5 — Complication thérapeutique.','Trouble respiratoire, de parole ou de déglutition après toxine.','Aide médicale immédiate.']]),(1,4,5,12))
l.add('L’anamnèse précise ce qui bouge, de quel côté et depuis quand. Les {questions ciblées} recherchent une irritation, un médicament ou un autre trouble moteur. Le retentissement quotidien fait partie de l’évaluation.',table(['Question','Orientation'],[['Fermeture complète ou simple frémissement ?','Caractériser le mouvement avant de le nommer.'],['Un œil, deux yeux, joue ou bouche associés ?','Distribution palpébrale ou hémifaciale.'],['Douleur, rougeur, photophobie, larmes ou vision diminuée ?','Maladie de surface ou urgence oculaire.'],['Lentilles, bricolage, projection, intervention ou traumatisme ?','Cause cornéenne et risque infectieux ou mécanique.'],['Fatigue, stimulants, stress ou manque de sommeil ?','Facteurs favorisants possibles, sans diagnostic automatique.'],['Nouveau médicament, changement de dose ou exposition ancienne ?','Cause médicamenteuse aiguë ou tardive.'],['Contact du visage améliorant les spasmes, envie préalable ou suppression brève ?','Indices de dystonie ou de tic à interpréter avec l’examen.'],['Lecture, conduite, chute ou isolement ?','Retentissement fonctionnel et besoins de soutien.']]),(1,2,6,7,8,10,11,13))
l.add('L’examen associe observation du mouvement et évaluation oculaire. Les {gestes utiles} recherchent les causes dangereuses avant de conclure à une dystonie. Il faut examiner les deux yeux et le reste du visage.',paras('Observer clignements et fermetures au repos, pendant la conversation et lors de tâches simples. Décrire synchronie, stéréotypie, durée, extension au bas du visage et éventuel geste antagoniste.', 'Mesurer l’acuité visuelle de chaque œil selon les possibilités, inspecter rougeur, bords palpébraux, cils, cornée et pupilles. Compléter motricité oculaire et examen neurologique si le tableau l’indique.', 'La lampe à fente et la fluorescéine sont utiles pour une atteinte de surface dans un cadre approprié. Une suspicion de plaie pénétrante modifie les gestes : ne pas forcer l’ouverture ni exercer une pression inutile sur le globe.'),(1,3,4,6,7,8))
l.add('L’{approche syndromique} distingue fermeture active, irritation et défaut d’ouverture. Les signes associés ont davantage de valeur qu’un symptôme isolé. Une sécheresse peut accompagner une dystonie plutôt que l’expliquer entièrement.',table(['Syndrome','Indices','Orientation'],[['7.1 — Dystonique.','Spasmes bilatéraux synchrones, parfois geste antagoniste.','Blépharospasme essentiel ou secondaire.'],['7.2 — Irritatif.','Douleur, rougeur, photophobie, larmoiement.','Cornée et surface à examiner.'],['7.3 — Frémissement localisé.','Mouvement limité sans fermeture forcée habituelle.','Myokymie à distinguer d’une extension faciale.'],['7.4 — Hémifacial.','Contractions d’un côté avec joue ou bouche.','Spasme hémifacial ou autre mouvement facial.'],['7.5 — Tic.','Mouvement bref, envie préalable ou retenue temporaire possibles.','Évaluation du répertoire de tics.'],['7.6 — Défaut d’ouverture.','Difficulté à initier la réouverture ou ptosis.','Apraxie, faiblesse ou trouble neurologique à différencier.']]),(1,6,7,8,10,11))
l.add('Le diagnostic commence par la description du mouvement. Les {diagnostics à confronter} associent maladies palpébrales, causes réflexes et imitateurs neurologiques. Le tableau ne constitue pas une liste exhaustive de toutes les urgences oculaires.',paras('Pour une dystonie palpébrale, rechercher des spasmes stéréotypés, bilatéraux et synchrones, puis un geste antagoniste ou un clignement accru. Ces critères soutiennent l’examen clinique mais n’ont pas une exactitude absolue.', 'Les performances de l’étude multicentrique de 2021 diffèrent de celles du petit travail initial cité dans les revues. Un seul seuil de clignements ou un questionnaire ne confirme donc pas le diagnostic dans toutes les situations.', 'Les uvéites, le glaucome aigu, les lésions neurologiques et un ptosis nécessitent aussi une démarche adaptée lorsqu’ils sont évoqués. Ils ne doivent pas être ignorés parce qu’ils ne font pas partie des dix monographies retenues.')+comparison(),(1,4,6,7,8,10,12,13))
l.add('Les examens complémentaires répondent à une hypothèse précise. Les {quatre niveaux du bilan} séparent diagnostic clinique, exploration oculaire et recherche neurologique ciblée. Une batterie d’examens normale ne remplace pas une bonne observation.',paras('9.a — Référence : examen clinique du mouvement avec bilan ophtalmologique adapté ; pas de biomarqueur unique du blépharospasme essentiel.', '9.b — Acuité, surface, paupières et lampe à fente selon le tableau ; fluorescéine pour une lésion épithéliale, mesure de pression et examen de chambre antérieure par le professionnel lorsque nécessaires.', '9.c — Imagerie ou examens neurologiques selon signes associés, atypies ou suspicion secondaire. Une forme typique isolée n’exige pas systématiquement une exploration extensive ; les examens fonctionnels de recherche ne sont pas des tests de routine.', '9.d — Revue médicamenteuse, documentation du retentissement et du traitement antérieur. Un ptosis avec fatigabilité ou une difficulté d’ouverture doit être exploré selon son mécanisme plutôt que classé comme spasme par défaut.'),(1,4,6,7,8,13))
l.add('L’{arbre décisionnel} donne priorité à l’œil menacé et aux signes neurologiques nouveaux. La suite dépend du mouvement réellement observé. Les symptômes persistants demandent une réévaluation plutôt qu’une simple réassurance répétée.',steps('Douleur importante, baisse visuelle, traumatisme, infiltrat ou signe neurologique nouveau → filière urgente adaptée.', 'Sans alarme → distinguer spasme, frémissement, tic, défaut d’ouverture ou ptosis.', 'Si irritation de surface → examiner et traiter la cause oculaire, puis réévaluer le mouvement.', 'Si spasmes bilatéraux compatibles avec une dystonie → évaluation spécialisée et recherche de contexte secondaire.', 'Si unilatéral avec extension faciale, atypies ou évolution persistante → bilan neurologique ou ophtalmologique ciblé.', 'Avant le suivi → préciser sécurité des activités, critères de recours et objectifs du traitement.'),(1,4,6,7,8,10,11,12))
drug=window(l)
l.add('La prise en charge dépend de la cause et du handicap. Les {modalités suisses} associent soins de surface, correction des facteurs favorisants et traitement spécialisé de la dystonie. La toxine botulique ne traite pas toute fermeture palpébrale.',paras('11.A — Préserver la vision et l’autonomie, soulager la cause et limiter les effets indésirables.', '11.B — Une affection cornéenne douloureuse ou une urgence profonde nécessite une prise en charge ophtalmologique. Ne pas utiliser empiriquement des corticoïdes oculaires devant une infection possible ; le guide HUG souligne ce risque, notamment pour l’herpès.', 'Pour une irritation ou une sécheresse identifiée, adapter les soins de surface et d’hygiène palpébrale. Pour une myokymie typique, revoir sommeil, stimulants et facteurs favorisants ; ne pas arrêter seul un médicament prescrit.', 'Le blépharospasme dystonique gênant peut relever d’injections de toxine botulique par un spécialiste. La fenêtre précise les unités, doses, âge et limites de BOTOX selon l’information suisse. Les autres toxines ne sont pas interchangeables unité pour unité.', 'Une protection lumineuse adaptée et les gestes antagonistes utiles au patient peuvent compléter le traitement. Une chirurgie n’est discutée que dans des situations sélectionnées ; aucune promesse de guérison n’est attachée aux injections.', '11.C — Contrôler fréquence des spasmes, capacité à garder les yeux ouverts, surface cornéenne et tolérance. Après toxine, surveiller notamment ptosis, diplopie, exposition cornéenne et symptômes généraux de diffusion.', '11.D — Organiser le suivi, les éventuelles répétitions et les adaptations du quotidien. Une fermeture compromettant la vision rend la conduite dangereuse ; réévaluer cette activité avec les soignants plutôt que se fier à une seule mesure d’acuité.')+paras(drug),(1,2,5,6,7,9,10,11))
l.add('La prévention vise les lésions oculaires et les complications fonctionnelles. Les {actions adaptées} distinguent réduction des irritants et suivi d’un trouble moteur. Aucune mesure certaine de prévention de la dystonie essentielle n’est établie ici.',paras('Primaire : protéger les yeux lors des activités à risque, respecter l’hygiène des lentilles et limiter les facteurs personnels favorisant les tressautements. Secondaire : faire évaluer douleur, rougeur, baisse visuelle ou mouvement persistant et ne pas attribuer tous les symptômes au stress. Tertiaire : suivre surface oculaire, réponse thérapeutique et sécurité quotidienne, tout en prenant en compte gêne sociale et retentissement psychologique.'),(1,2,6,7,10,11))
l.add('Une paupière qui tressaute n’est pas toujours un blépharospasme dystonique. Douleur, baisse visuelle ou traumatisme font rechercher une urgence oculaire. La distribution du mouvement distingue les principales hypothèses. Les unités et limites de la toxine botulique dépendent du produit.',refs=(1,5,6,7,8,10))
l.quiz([
('Une fermeture douloureuse de l’œil prouve-t-elle une dystonie ?','Non : une irritation ou une atteinte cornéenne peut provoquer une fermeture réflexe.'),
('Quel muscle ferme les paupières ?','L’orbiculaire, sous la commande du nerf facial.'),
('Le releveur et l’orbiculaire ont-ils le même rôle ?','Non : le releveur participe à l’ouverture, l’orbiculaire à la fermeture.'),
('Un geste antagoniste signifie-t-il que les spasmes sont volontaires ?','Non : une modulation sensorielle peut diminuer une dystonie.'),
('Une sécheresse exclut-elle un blépharospasme essentiel associé ?','Non : les deux peuvent coexister.'),
('Quel tableau doit faire craindre une kératite ?','Œil rouge douloureux avec photophobie, blépharospasme et parfois baisse visuelle.'),
('Un porteur de lentilles douloureux peut-il être simplement rassuré ?','Non : une atteinte cornéenne infectieuse doit notamment être recherchée.'),
('Une myokymie localisée se confond-elle toujours avec une fermeture forcée ?','Non : le mouvement doit être décrit et examiné.'),
('Des contractions de la joue et de la bouche d’un seul côté orientent-elles le bilan ?','Oui : elles font notamment rechercher un spasme hémifacial.'),
('Un ptosis est-il une contraction involontaire identique au blépharospasme ?','Non : c’est une paupière tombante, dont le mécanisme est différent.'),
('Les critères cliniques ont-ils une exactitude parfaite ?','Non : ils soutiennent l’examen sans remplacer le diagnostic différentiel.'),
('Peut-on convertir directement les unités de BOTOX en celles d’une autre toxine ?','Non : les unités ne sont pas interchangeables.'),
('Un trouble de déglutition ou de respiration après injection peut-il attendre le contrôle prévu ?','Non : une aide médicale immédiate est nécessaire.'),
('Une acuité normale entre deux spasmes garantit-elle une conduite sûre ?','Non : la fermeture involontaire peut compromettre la vision pendant la conduite.')],(1,3,4,5,6,7,8,10,11))
l.write()
